{
  "hooks": {
    "PostCompact": [
      {
        "hooks": [
          {
            "command": "'./bin/agent-harness' hook post-compact",
            "timeout": 5,
            "type": "command"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "hooks": [
          {
            "command": "'./bin/agent-harness' hook post-tool-use",
            "timeout": 5,
            "type": "command"
          }
        ],
        "matcher": "*"
      }
    ],
    "PreCompact": [
      {
        "hooks": [
          {
            "command": "'./bin/agent-harness' hook pre-compact",
            "timeout": 5,
            "type": "command"
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "command": "'./bin/agent-harness' hook session-start",
            "timeout": 5,
            "type": "command"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "command": "'./bin/agent-harness' hook stop",
            "timeout": 5,
            "type": "command"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "command": "'./bin/agent-harness' hook user-prompt",
            "timeout": 5,
            "type": "command"
          }
        ]
      }
    ]
  }
}

